                cells=[(i,j)]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    a,b=q.popleft()
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<H and 0<=nb<W and I[na][nb]==bg and not seen[na][nb]:
                            seen[na][nb]=True;q.append((na,nb));cells.append((na,nb))
                rs=[r for r,_ in cells]; cs=[c for _,c in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if any(r==0 or r==H-1 or c==0 or c==W-1 for r,c in cells): continue
                S=set(cells)
                top=all(I[r0][j]==line for j in range(c0,c1+1) if (r0,j) not in S)
                bot=all(I[r1][j]==line for j in range(c0,c1+1) if (r1,j) not in S)
                lef=all(I[i][c0]==line for i in range(r0,r1+1) if (i,c0) not in S)
                rig=all(I[i][c1]==line for i in range(r0,r1+1) if (i,c1) not in S)
                solid=True
                for r in range(r0,r1+1):
                    for c in range(c0,c1+1):
                        if (r,c) not in S: solid=False
                if top and bot and lef and rig and solid:
                    for (r,c) in cells: out[r][c]=4
    return out
